using System.ComponentModel;
using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Optional desired length: short, medium, or long.")] string length = "medium")
    {
        yield return new ChatMessage(
            ChatRole.User,
            $"""
            Please provide a {length} summary of the following text.
            Focus on the key points and main ideas.

            Text:
            {content}
            """);
    }
}

